    """Replace the consecutive follow-up paragraphs.

    Returns (changed, inserted_paragraph_count, removed_cache_elem_count)
    """

    # For this task, follow-ups are simple top-level <hp:p> in section1.
    ps = section_root.findall("./hp:p", NS)

    # Locate the old followup block: consecutive paragraphs whose text looks like "N. ..."
    start = None
    end = None
    for i, p in enumerate(ps):
        txt = get_paragraph_text(p).strip()
        if re.match(r"^1\.\s+", txt):
            start = i
            j = i
            while j < len(ps) and re.match(r"^\d+\.\s+", (get_paragraph_text(ps[j]).strip())):
                j += 1
            end = j  # exclusive
            break

    if start is None or end is None or end <= start:
        return (False, 0, 0)

    template = ps[start]

    # Remove the old block first so we can avoid ID collisions with remaining paragraphs.
    for p in ps[start:end]:
        section_root.remove(p)

    # Gather existing paragraph IDs (anywhere in this section).
    existing_ids = set()
    numeric_ids = []
    for p in section_root.findall(".//hp:p", NS):
        pid = p.get("id")
        if pid is None:
            continue
        existing_ids.add(pid)
        try:
            numeric_ids.append(int(pid))
        except Exception:
            pass

    def next_unused_id(start_from: int) -> str:
        cur = start_from
        while str(cur) in existing_ids:
            cur += 1
        existing_ids.add(str(cur))
        return str(cur)

    # Prefer reusing the old block's starting ID (e.g., 41), but ensure uniqueness.
    try:
        start_id_num = int(template.get("id") or "")
    except Exception:
        start_id_num = (max(numeric_ids) + 1) if numeric_ids else 0

    removed_cache = 0
    inserted = 0
    for idx, item in enumerate(new_items, start=1):
        new_p = copy.deepcopy(template)
        if APPENDIX_SENTENCE in get_paragraph_text(new_p):
            continue

        new_p.set("id", next_unused_id(start_id_num + (idx - 1)))
        set_paragraph_text_flat(new_p, f"{idx}. {item}")
        section_root.insert(start + inserted, new_p)
        removed_cache += remove_layout_cache_in_place(new_p)
        inserted += 1

    return (True, inserted, removed_cache)

